class Player {
    constructor(x, color, name, controls) {
        this.x = x; this.y = GROUND_Y;
        this.width = 50; this.height = 80;
        this.color = color; this.name = name;
        this.vx = 0; this.vy = 0;
        this.health = 100; this.maxHealth = 100;
        this.isAttacking = false; this.attackFrame = 0;
        this.attackCooldown = 0; this.attackType = 0;
        this.facingRight = true;
        this.controls = controls;
        this.isJumping = false;
        this.isBlocking = false;
        this.blockStun = 0;
        this.speed = 5; this.power = 10;
        this.speedBuff = 0; this.powerBuff = 0;
        this.shieldActive = false; this.shieldTimer = 0;
        this.hitStun = 0; this.animFrame = 0;
        this.specialCharge = 0; this.specialReady = false;
        this.wins = 0;
    }
    attack(type) {
        if (this.attackCooldown > 0 || this.hitStun > 0 || this.blockStun > 0) return false;
        this.isAttacking = true;
        this.attackFrame = 0;
        this.attackType = type || 0;
        this.attackCooldown = type === 2 ? 40 : 20;
        return true;
    }
    specialAttack() {
        if (!this.specialReady || this.attackCooldown > 0 || this.hitStun > 0) return false;
        this.specialReady = false;
        this.specialCharge = 0;
        this.isAttacking = true;
        this.attackFrame = 0;
        this.attackType = 3;
        this.attackCooldown = 50;
        return true;
    }
    takeDamage(dmg) {
        if (this.shieldActive) {
            dmg = Math.floor(dmg * 0.3);
            this.shieldActive = false;
            this.shieldTimer = 0;
            spawnParticles(this.x + this.width/2, this.y - this.height/2, '#44aaff', 10, 4);
        }
        if (this.isBlocking) {
            dmg = Math.floor(dmg * 0.2);
            this.blockStun = 10;
            spawnParticles(this.x + this.width/2, this.y - this.height/2, '#ffffff', 5, 2);
        }
        this.health = Math.max(0, this.health - dmg);
        this.hitStun = 8;
        screenShake = 6;
        return dmg;
    }
    applyPowerUp(pu) {
        switch(pu.type.name) {
            case 'SPEED': this.speedBuff = pu.type.duration; this.speed = 8; break;
            case 'POWER': this.powerBuff = pu.type.duration; this.power = 18; break;
            case 'SHIELD': this.shieldActive = true; this.shieldTimer = pu.type.duration; break;
            case 'HEAL': this.health = Math.min(this.maxHealth, this.health + 30); break;
        }
        spawnParticles(this.x + this.width/2, this.y - this.height/2, pu.type.color, 15, 5);
    }
    getAttackBox() {
        let range = this.attackType === 2 ? 80 : this.attackType === 3 ? 120 : 60;
        let dmg = this.attackType === 2 ? this.power * 1.5 : this.attackType === 3 ? this.power * 2.5 : this.power;
        dmg = Math.floor(dmg);
        let bx = this.facingRight ? this.x + this.width : this.x - range;
        return { x: bx, y: this.y - this.height, w: range, h: this.height, dmg: dmg };
    }
    update() {
        if (this.hitStun > 0) this.hitStun--;
        if (this.blockStun > 0) this.blockStun--;
        if (this.attackCooldown > 0) this.attackCooldown--;
        if (this.speedBuff > 0) { this.speedBuff--; if (this.speedBuff <= 0) this.speed = 5; }
        if (this.powerBuff > 0) { this.powerBuff--; if (this.powerBuff <= 0) this.power = 10; }
        if (this.shieldTimer > 0) { this.shieldTimer--; if (this.shieldTimer <= 0) this.shieldActive = false; }
        if (this.isAttacking) { this.attackFrame++; if (this.attackFrame > 12) this.isAttacking = false; }
        this.vy += GRAVITY;
        this.x += this.vx; this.y += this.vy;
        if (this.y >= GROUND_Y) {
            if (this.isJumping) spawnDust(this.x + this.width/2, GROUND_Y);
            this.y = GROUND_Y; this.vy = 0; this.isJumping = false;
        }
        this.x = Math.max(0, Math.min(canvas.width - this.width, this.x));
        this.vx *= 0.85;
        this.animFrame++;
    }
    jump() {
        if (!this.isJumping && this.hitStun <= 0) {
            this.vy = JUMP_FORCE; this.isJumping = true;
            spawnParticles(this.x + this.width/2, this.y, '#aaa', 6, 3);
        }
    }
    draw() {
        let cx = this.x + this.width/2;
        let cy = this.y - this.height/2;
        let dir = this.facingRight ? 1 : -1;
        // Shield glow
        if (this.shieldActive) {
            ctx.strokeStyle = '#44aaff';
            ctx.lineWidth = 3;
            ctx.shadowColor = '#44aaff';
            ctx.shadowBlur = 15;
            ctx.beginPath();
            ctx.ellipse(cx, cy, this.width/2 + 8, this.height/2 + 8, 0, 0, Math.PI*2);
            ctx.stroke();
            ctx.shadowBlur = 0;
        }
        // Body
        let bodyGrad = ctx.createLinearGradient(this.x, this.y - this.height, this.x, this.y);
        bodyGrad.addColorStop(0, this.color);
        bodyGrad.addColorStop(1, this.darken(this.color, 40));
        ctx.fillStyle = bodyGrad;
        // Torso
        ctx.fillRect(this.x + 10, this.y - this.height + 15, this.width - 20, 35);
        // Head
        ctx.beginPath();
        ctx.arc(cx, this.y - this.height + 10, 14, 0, Math.PI * 2);
        ctx.fill();
        // Eyes
        ctx.fillStyle = '#fff';
        ctx.beginPath();
        ctx.arc(cx + dir * 5, this.y - this.height + 8, 3, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = '#000';
        ctx.beginPath();
        ctx.arc(cx + dir * 6, this.y - this.height + 8, 1.5, 0, Math.PI * 2);
        ctx.fill();
        // Legs
        let legAnim = this.isJumping ? 8 : Math.sin(this.animFrame * 0.15) * (Math.abs(this.vx) > 0.5 ? 6 : 0);
        ctx.fillStyle = this.darken(this.color, 60);
        ctx.fillRect(this.x + 12, this.y - 30 + legAnim, 10, 30 - legAnim);
        ctx.fillRect(this.x + this.width - 22, this.y - 30 - legAnim, 10, 30 + legAnim);
        // Arms
        if (this.isAttacking) {
            let ext = this.attackType === 3 ? 45 : this.attackType === 2 ? 35 : 25;
            ctx.fillStyle = this.color;
            ctx.fillRect(cx + dir * 15, cy - 5, dir * ext, 10);
            // Fist
            ctx.fillStyle = this.attackType === 3 ? '#ff0' : this.attackType === 2 ? '#f80' : '#fff';
            ctx.beginPath();
            ctx.arc(cx + dir * (15 + ext), cy, this.attackType === 3 ? 8 : 6, 0, Math.PI * 2);
            ctx.fill();
            if (this.attackType === 3) {
                ctx.shadowColor = '#ff0';
                ctx.shadowBlur = 20;
                ctx.fill();
                ctx.shadowBlur = 0;
            }
        } else if (this.isBlocking) {
            ctx.fillStyle = this.color;
            ctx.fillRect(cx - 5, cy - 15, 10, 30);
            ctx.fillStyle = '#fff';
            ctx.font = '10px Arial';
            ctx.textAlign = 'center';
            ctx.fillText('BLOCK', cx, cy - 20);
        } else {
            ctx.fillStyle = this.color;
            ctx.fillRect(cx - dir * 20, cy - 5, 15, 10);
            ctx.fillRect(cx + dir * 5, cy - 5, 15, 10);
        }
        // Buff indicators
        let buffs = [];
        if (this.speedBuff > 0) buffs.push({t:'SPD', c:'#00ff88'});
        if (this.powerBuff > 0) buffs.push({t:'PWR', c:'#ff4444'});
        buffs.forEach((b, i) => {
            ctx.fillStyle = b.c;
            ctx.font = 'bold 9px Arial';
            ctx.textAlign = 'center';
            ctx.fillText(b.t, cx, this.y - this.height - 25 - i * 12);
        });
        // Special charge bar
        if (this.specialCharge > 0) {
            let barW = 40;
            let pct = Math.min(1, this.specialCharge / 100);
            ctx.fillStyle = '#333';
            ctx.fillRect(cx - barW/2, this.y - this.height - 10, barW, 4);
            ctx.fillStyle = this.specialReady ? '#ff0' : '#f80';
            ctx.fillRect(cx - barW/2, this.y - this.height - 10, barW * pct, 4);
            if (this.specialReady) {
                ctx.fillStyle = '#ff0';
                ctx.font = 'bold 8px Arial';
                ctx.fillText('MAX!', cx, this.y - this.height - 14);
            }
        }
    }
    darken(hex, amt) {
        let r = parseInt(hex.slice(1,3),16) - amt;
        let g = parseInt(hex.slice(3,5),16) - amt;
        let b = parseInt(hex.slice(5,7),16) - amt;
        return '#' + [r,g,b].map(v => Math.max(0,v).toString(16).padStart(2,'0')).join('');
    }
}
