// Game objects
let player1, player2;
const keys = {};

function initGame() {
    player1 = new Player(100, '#ff4444', 'Player 1', {left:'a',right:'d',up:'w',down:'s',attack:'f',special:'g',block:'s'});
    player2 = new Player(550, '#4488ff', 'Player 2', {left:'arrowleft',right:'arrowright',up:'arrowup',down:'arrowdown',attack:'m',special:'n',block:'arrowdown'});
    player1.wins = p1Wins; player2.wins = p2Wins;
    particles = []; powerUps = []; powerUpTimer = 0;
    comboP1 = 0; comboP2 = 0; comboTimerP1 = 0; comboTimerP2 = 0;
    gameRunning = true; gameOver = false;
    status.textContent = 'Round ' + roundNum + ' - FIGHT!';
}

function checkCollision(box, player) {
    return box.x < player.x + player.width && box.x + box.w > player.x &&
           box.y < player.y && box.y + box.h > player.y - player.height;
}

function checkPowerUpCollision(player) {
    for (let i = powerUps.length - 1; i >= 0; i--) {
        let pu = powerUps[i];
        let px = player.x + player.width/2, py = player.y - player.height/2;
        if (Math.abs(px - pu.x) < 30 && Math.abs(py - pu.y) < 40) {
            player.applyPowerUp(pu);
            powerUps.splice(i, 1);
        }
    }
}

function update() {
    if (!gameRunning || gameOver) return;
    // P1 controls
    if (keys['a']) { player1.vx = -player1.speed; player1.facingRight = false; }
    if (keys['d']) { player1.vx = player1.speed; player1.facingRight = true; }
    if (keys['w']) player1.jump();
    player1.isBlocking = !!keys['s'];
    if (keys['f'] && player1.attack(0)) {
        let ab = player1.getAttackBox();
        if (checkCollision(ab, player2)) {
            let dmg = player2.takeDamage(ab.dmg);
            player1.specialCharge = Math.min(100, player1.specialCharge + 15);
            comboP1++; comboTimerP1 = 60;
            spawnParticles(player2.x + player2.width/2, player2.y - player2.height/2, '#ff4444', 8, 4);
        }
    }
    if (keys['g'] && player1.specialAttack()) {
        let ab = player1.getAttackBox();
        if (checkCollision(ab, player2)) {
            let dmg = player2.takeDamage(ab.dmg);
            spawnParticles(player2.x + player2.width/2, player2.y - player2.height/2, '#ff0', 20, 6);
            screenShake = 12;
        }
    }
    // P2 controls
    if (keys['arrowleft']) { player2.vx = -player2.speed; player2.facingRight = false; }
    if (keys['arrowright']) { player2.vx = player2.speed; player2.facingRight = true; }
    if (keys['arrowup']) player2.jump();
    player2.isBlocking = !!keys['arrowdown'];
    if (keys['m'] && player2.attack(0)) {
        let ab = player2.getAttackBox();
        if (checkCollision(ab, player1)) {
            let dmg = player1.takeDamage(ab.dmg);
            player2.specialCharge = Math.min(100, player2.specialCharge + 15);
            comboP2++; comboTimerP2 = 60;
            spawnParticles(player1.x + player1.width/2, player1.y - player1.height/2, '#4488ff', 8, 4);
        }
    }
    if (keys['n'] && player2.specialAttack()) {
        let ab = player2.getAttackBox();
        if (checkCollision(ab, player1)) {
            let dmg = player1.takeDamage(ab.dmg);
            spawnParticles(player1.x + player1.width/2, player1.y - player1.height/2, '#ff0', 20, 6);
            screenShake = 12;
        }
    }
    // Face each other
    if (player1.x < player2.x) { player1.facingRight = true; player2.facingRight = false; }
    else { player1.facingRight = false; player2.facingRight = true; }
    // Update
    player1.update(); player2.update();
    checkPowerUpCollision(player1); checkPowerUpCollision(player2);
    // Particles
    particles = particles.filter(p => { p.update(); return p.life > 0; });
    // PowerUps
    powerUpTimer++;
    if (powerUpTimer > 300 && powerUps.length < 2) {
        powerUps.push(new PowerUp());
        powerUpTimer = 0;
    }
    powerUps = powerUps.filter(p => { p.update(); return p.life > 0; });
    // Combos
    if (comboTimerP1 > 0) comboTimerP1--; else comboP1 = 0;
    if (comboTimerP2 > 0) comboTimerP2--; else comboP2 = 0;
    // Screen shake
    if (screenShake > 0) screenShake *= 0.85;
    if (screenShake < 0.5) screenShake = 0;
    // Win check
    if (player1.health <= 0 || player2.health <= 0) {
        gameOver = true;
        if (player1.health <= 0) { player2.wins++; p2Wins = player2.wins; }
        if (player2.health <= 0) { player1.wins++; p1Wins = player1.wins; }
